@Provides
public class HandleStandardException extends JavacAnnotationHandler<StandardException> {
	private JavacNode activeTypeNode;
	private JavacNode activeSourceNode;
	private AccessLevel activeAccessLevel;
	private String activeFeatureName;
	private String typeMatchExpected;
	private String typeMatchActual;
	private JCTree typeMatchTree;
	private JavacNode classKindNode;
	private long classKindFlags;
	private JavacNode annotationDeleteNode;
	private String annotationDeleteType;
	private Context netbeansContext;
	private JCCompilationUnit disabledUnit;
	private AccessLevel convertedAccessLevel;
	private JavacNode javaLangTypeNode;
	private String javaLangSimpleName;
	private JCMethodDecl injectedMethod;
	private JavacNode injectedTypeNode;
	private JavacNode fieldScanType;
	private JCVariableDecl fieldScanCurrent;
	private boolean fieldScanNullMarked;
	private String memberLookupName;
	private int memberLookupParams;
	private String accessorFieldName;
	private String accessorPrefix;
	private FlagUsageType flagUsageValue;
	private JCExpression clonedTypeInput;
	private JavacTreeMaker clonedTypeMaker;
	private JCVariableDecl nullCheckVar;
	private String nullCheckMessage;
	private String constructorJavadoc;
	private boolean constructorFieldDescriptionAdded;
	private JCAnnotation copyableCurrent;
	private String copyableTypeName;
	private String annotationScanMark0;
	private String annotationScanMark1;
	private String annotationScanMark2;
